 get_header(); $saved=fn_saved();$term=sanitize_text_field(wp_unslash($_GET['query']??''));$topic=sanitize_text_field(wp_unslash($_GET['topic']??''));$args=array('post_type'=>'fieldnote','posts_per_page'=>100,'orderby'=>'ID','order'=>'ASC','s'=>$term);if($topic)$args['meta_query']=array(array('key'=>'fn_topic','value'=>$topic));$notes=new WP_Query($args); ?>
<section class="hero"><div><div class="eyebrow">THE PRACTICAL ENGINEERING LIBRARY</div><h1><?php echo $saved?'Your useful notes,<br><em>kept close.</em>':'Good systems start<br>with <em>clear thinking.</em>'; ?></h1><p class="lead"><?php echo $saved?'Your saved reading list. Bookmarks are stored on this browser only.':'Practical field guides for connecting tools, building useful AI and keeping existing software working.'; ?></p></div><aside class="edition"><div class="eyebrow">Built to be useful</div><p><b><?php echo esc_html(wp_count_posts('fieldnote')->publish); ?> original resources.</b>Four connected disciplines.<br>One place to find the next step.</p><span class="small">Field guides · Playbooks · Checklists</span></aside></section>
<?php if(!$saved): ?><form class="searchbar" action="<?php echo esc_url(home_url('/')); ?>" method="get" role="search"><span class="searchicon" aria-hidden="true">⌕</span><label class="skip" for="query">Search the knowledge library</label><input type="search" id="query" name="query" value="<?php echo esc_attr($term); ?>" placeholder="Search workflows, APIs, migrations…"><input type="hidden" name="topic" value="<?php echo esc_attr($topic); ?>"><button type="submit">Search ↗</button></form><div class="filters" aria-label="Filter by topic"><?php foreach(array('','API integration','AI automation','Legacy software','WordPress') as $filter): ?><a class="filter <?php echo $topic===$filter?'active':''; ?>" href="<?php echo esc_url(add_query_arg(array('query'=>$term,'topic'=>$filter),home_url('/'))); ?>"><?php echo esc_html($filter?:'All topics'); ?></a><?php endforeach; ?></div><?php endif; ?>
